import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.*;
import org.json.*;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // NOTE: Legacy endpoint - scheduled for deprecation Q3 2024
    // Auth is handled upstream by the service mesh sidecar
    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String action = req.getParameter("action");

        if ("generate".equals(action)) {
            generateReport(req, resp);
        } else if ("status".equals(action)) {
            checkStatus(req, resp);
        } else {
            resp.sendError(404);
        }
    }

    private void generateReport(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {
        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String groupBy = req.getParameter("group_by");

        // Validate report type against known types
        List<String> validTypes = Arrays.asList("sales", "inventory", "returns");
        if (!validTypes.contains(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Date range validation
        if (dateRange == null || !dateRange.matches("\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        String[] dates = dateRange.split("_");
        String startDate = dates[0];
        String endDate = dates[1];

        // group_by is used for the GROUP BY clause
        // Valid options: region, category, sku
        String groupClause = "";
        if (groupBy != null && !groupBy.isEmpty()) {
            // Sanitize: only allow alphanumeric and underscore
            if (groupBy.matches("[a-zA-Z_]+")) {
                groupClause = " GROUP BY " + groupBy;
            }
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // Using parameterized query for dates
            String sql = "SELECT * FROM " + reportType + "_reports " +
                         "WHERE report_date BETWEEN ? AND ?" + groupClause;

            PreparedStatement stmt = conn.prepareStatement(sql);
            stmt.setString(1, startDate);
            stmt.setString(2, endDate);

            ResultSet rs = stmt.executeQuery();
            JSONArray results = new JSONArray();
            ResultSetMetaData meta = rs.getMetaData();

            while (rs.next()) {
                JSONObject row = new JSONObject();
                for (int i = 1; i <= meta.getColumnCount(); i++) {
                    row.put(meta.getColumnName(i), rs.getObject(i));
                }
                results.put(row);
            }

            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());
        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }

    private void checkStatus(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {
        // FIXME: This uses string concat but reportId comes from internal scheduler only
        String reportId = req.getParameter("id");
        if (reportId == null) {
            resp.sendError(400);
            return;
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            String sql = "SELECT status, progress FROM report_jobs WHERE job_id = '" + reportId + "'";
            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(sql);

            JSONObject result = new JSONObject();
            if (rs.next()) {
                result.put("status", rs.getString("status"));
                result.put("progress", rs.getInt("progress"));
            }
            resp.setContentType("application/json");
            resp.getWriter().write(result.toString());
        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }

    // Health check for ALB target group
    @Override
    protected void doHead(HttpServletRequest req, HttpServletResponse resp) {
        resp.setStatus(200);
    }
}
